    const MAX_VALUES = { '支配欲': 150, '反抗意志': 150, '好感': 100, '爱意': 150, '情欲': 100 };
    const oldValues = {};

    function getVal(obj, key, fallback = '--') { const val = obj?.[key]?.[0]; return val !== null && val !== undefined ? String(val) : fallback; }
    function setField(id, value, isHtml = false) { const el = document.getElementById(id); if (el) { isHtml ? el.innerHTML = value : el.innerText = value; } }

    function animateNumberUpdate(element, start, end, isWQ) {
        if (!element || start === end) { if(element) element.innerText = end; return; }
        let duration = 400; let frameRate = 20; let totalFrames = duration / frameRate; let currentFrame = 0;
        const update = () => {
            currentFrame++;
            if (currentFrame >= totalFrames) { element.innerText = end; clearInterval(interval); return; }
            if (isWQ) { element.style.opacity = currentFrame / totalFrames; } 
            else { element.innerText = Math.floor(Math.random() * 100); }
        };
        if(isWQ) { element.style.opacity = 0; element.innerText = end; }
        const interval = setInterval(update, frameRate);
