        const match = reasonStr.match(/([+-]?\d+点?)/);
        let points = '', reason = reasonStr;
        if (match) { points = match[1].replace('点', ''); reason = reasonStr.replace(match[0], '').replace(/^,?\\s*/, ''); }
        const pointsHtml = points ? `<div class="tooltip-points">${points}</div>` : '';
        setField(elementId, `${pointsHtml}<div class="tooltip-text">${reason}</div>`, true);
    }

    function renderInteractiveMonologue(text) {
        if (!text) return '...';
        const regex = /\[([^|\]]+)\|([^\]]+)\]/g;
        return text.replace(regex, `<span class="keyword">$1<span class="tooltip">$2</span></span>`);
    }

    function populateChar(prefix, charData) {
        const panel = document.getElementById(`${prefix}-panel`);
        if (!panel) return;
        panel.style.display = getVal(charData, '位置') !== '不在场' ? 'block' : 'none';

        const isWQ = prefix === 'wq';
        const mainStatKey = isWQ ? '支配欲' : '反抗意志';
        const mainStatVal = parseInt(getVal(charData, mainStatKey, 0));

        const statMapping = { 'dominance': '支配欲', 'resistance': '反抗意志', 'favor': '好感', 'love': '爱意' };
        Object.keys(statMapping).forEach(s => {
            const statKey = statMapping[s];
            if ((isWQ && (s === 'dominance' || s === 'favor' || s === 'love')) || (!isWQ && (s === 'resistance' || s === 'favor' || s === 'love'))) {
                const valEl = document.getElementById(`${prefix}-${s}-val`);
                const barEl = document.getElementById(`${prefix}-${s}-bar`);
                const reasonElId = `${prefix}-${s}-reason`;

                const newValue = parseInt(getVal(charData, statKey, 0));
                const oldValue = oldValues[`${prefix}_${statKey}`] || newValue;

                if (valEl) animateNumberUpdate(valEl, oldValue, newValue, isWQ);
                if (barEl) barEl.style.width = (newValue / MAX_VALUES[statKey]) * 100 + '%';
                setTooltipContent(reasonElId, getVal(charData, `${statKey}_更新原因`));
                oldValues[`${prefix}_${statKey}`] = newValue;
            }
        });

        panel.classList.toggle('alert-glow', mainStatVal >= 100);

        const emotionValue = parseInt(getVal(charData, '情欲', 0));
        const visualizer = document.getElementById(`${prefix}-visualizer`);
        if (visualizer && visualizer.firstElementChild) {
            let speed = 2.5 - (emotionValue / MAX_VALUES['情欲']) * 2;
            visualizer.firstElementChild.style.animationDuration = Math.max(0.5, speed) + 's';
        }

        setField(`${prefix}-stage`, getVal(charData, '角色阶段'));
        const detailsContent = `
            <ul>
                <li><span class="label">📍 位置:</span>${getVal(charData, '位置')}</li>
                <li><span class="label">👗 衣着:</span>${getVal(charData, '当前衣着')}</li>
                <li><span class="label">💓 状态:</span>${getVal(charData, '身体状态')}</li>
                <li><span class="label">👉 行为:</span>${getVal(charData, '当前行为')}</li>
                <li><span class="label">💬 独白:</span><span class="monologue-text">${renderInteractiveMonologue(getVal(charData, '内心独白'))}</span></li>
            </ul>`;
        setField(`${prefix}-details`, detailsContent, true);
    }

    function populateWorldInfo(worldData) {
        if(!worldData) return;
        const date = getVal(worldData, '当前日期', '');
        const time = getVal(worldData, '当前时间段', '');
        setField('world-info-bar', `🕒 ${date} ${time}`);
    }

    let retries = 0;
    async function fetchData(msgId) {
        try {
            if (typeof getChatMessages !== 'function') { populateWorldInfo(initialData.世界); populateChar('wq', initialData.苏晚晴); populateChar('zy', initialData.夏知遥); return; }
            const messages = await getChatMessages(msgId);
            const data = messages?.[0]?.data?.stat_data;
            if (data && data.世界 && data.苏晚晴 && data.夏知遥) { populateWorldInfo(data.世界); populateChar('wq', data.苏晚晴); populateChar('zy', data.夏知遥); } 
            else {
                if(retries < 5) { retries++; setTimeout(()=>fetchData(msgId), 300); } 
                else { populateWorldInfo(initialData.世界); populateChar('wq', initialData.苏晚晴); populateChar('zy', initialData.夏知遥); }
            }
        } catch (error) { populateWorldInfo(initialData.世界); populateChar('wq', initialData.苏晚晴); populateChar('zy', initialData.夏知遥); }
    }
    try { const id = typeof getCurrentMessageId === 'function' ? getCurrentMessageId() : 0; setTimeout(() => fetchData(id), 100); }
    catch(e) { populateWorldInfo(initialData.世界); populateChar('wq', initialData.苏晚晴); populateChar('zy', initialData.夏知遥); }
})();
</script>
