    const MAX_VALUES = { '支配欲': 150, '反抗意志': 150, '好感': 100, '爱意': 150 };

    function getVal(obj, key, fallback = '--') { const val = obj?.[key]?.[0]; return val !== null && val !== undefined ? String(val) : fallback; }
    function setField(id, value, isHtml = false) { const el = document.getElementById(id); if (el) { isHtml ? el.innerHTML = value : el.innerText = value; } }

    function updateProgressBar(valId, barId, value, max_value) {
        let numValue = parseInt(value);
        if (isNaN(numValue)) { setField(valId, '--'); document.getElementById(barId).style.width = '0%'; return; }
        let percentage = (numValue / max_value) * 100;
        percentage = Math.max(0, Math.min(100, percentage));
        setField(valId, numValue);
        const barEl = document.getElementById(barId); if(barEl) barEl.style.width = `${percentage}%`;
