        const mainStatKey = prefix === 'wq' ? '支配欲' : '反抗意志';
        const mainStatValId = prefix === 'wq' ? 'wq-dominance-val-mobile' : 'zy-resistance-val-mobile';
        const mainStatBarId = prefix === 'wq' ? 'wq-dominance-bar-mobile' : 'zy-resistance-bar-mobile';

        setField(`${prefix}-stage-mobile`, getVal(charData, '角色阶段'));
        updateProgressBar(mainStatValId, mainStatBarId, getVal(charData, mainStatKey), MAX_VALUES[mainStatKey]);
        updateProgressBar(`${prefix}-favor-val-mobile`, `${prefix}-favor-bar-mobile`, getVal(charData, '好感'), MAX_VALUES['好感']);
        updateProgressBar(`${prefix}-love-val-mobile`, `${prefix}-love-bar-mobile`, getVal(charData, '爱意'), MAX_VALUES['爱意']);

        const detailsHtml = 
