            `<li><span class="icon">👉</span><span>${getVal(charData, '当前行为')}</span></li>` +
            `<li><span class="icon">💬</span><i>${getVal(charData, '内心独白')}</i></li>`;
        setField(`${prefix}-details-list-mobile`, detailsHtml, true);
    }

    function populateWorldInfo(worldData) {
        if(!worldData) return;
        const date = getVal(worldData, '当前日期', '');
        const time = getVal(worldData, '当前时间段', '');
        setField('world-info-mobile', `🕒 ${date} ${time}`);
    }

    let retries = 0;
    async function fetchDataMobile(msgId) {
        try {
            if (typeof getChatMessages !== 'function') {
                populateWorldInfo(initialData.世界);
                populateCharMobile('wq', initialData.苏晚晴);
                populateCharMobile('zy', initialData.夏知遥);
                return;
            }
            const messages = await getChatMessages(msgId);
            const data = messages?.[0]?.data?.stat_data;
            if (data && data.世界 && data.苏晚晴 && data.夏知遥) {
                populateWorldInfo(data.世界);
                populateCharMobile('wq', data.苏晚晴);
                populateCharMobile('zy', data.夏知遥);
            } else {
                if (retries < 5) { retries++; setTimeout(() => fetchDataMobile(msgId), 300); } 
                else {
                    populateWorldInfo(initialData.世界);
                    populateCharMobile('wq', initialData.苏晚晴);
                    populateCharMobile('zy', initialData.夏知遥);
                }
            }
        } catch (error) {
            populateWorldInfo(initialData.世界);
            populateCharMobile('wq', initialData.苏晚晴);
            populateCharMobile('zy', initialData.夏知遥);
        }
    }
    try { const id = typeof getCurrentMessageId === 'function' ? getCurrentMessageId() : 0; setTimeout(() => fetchDataMobile(id), 100); }
    catch(e) {
        populateWorldInfo(initialData.世界);
        populateCharMobile('wq', initialData.苏晚晴);
        populateCharMobile('zy', initialData.夏知遥);
    }
})();
